#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_INPUT_LEN 1024

int main(int argc, char *argv[])
{
    if (argc != 2) {
        return 0;
    }
    const char *input = argv[1];
    size_t input_len = strlen(input);
    if (input_len > MAX_INPUT_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    char norm_buf[MAX_INPUT_LEN + 1];
    size_t norm_len = 0;
    for (size_t i = 0; i < input_len; ++i) {
        unsigned char ch = (unsigned char)input[i];
        if (isalnum(ch)) {
            norm_buf[norm_len++] = (char)toupper(ch);
        }
    }
    norm_buf[norm_len] = '\0';
    int is_palindrome = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm_buf[i] != norm_buf[norm_len - 1 - i]) {
            is_palindrome = 0;
            break;
        }
    }
    if (is_palindrome) {
        puts("PALINDROME");
    } else {
        puts("NOT_PALINDROME");
    }
    return 0;
}
